fn frame(t: i32) {
    host::display::clear(0x0c0c0c);
    host::display::draw_string(8, 8, "DASHBOARD", 0xffffff, 2);
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, host::compose::spawn_module("clock", 16, 60, 224, 168));
        host::display::state_set(2, host::compose::spawn_module("ticker", 272, 60, 224, 168));
    }
    let a: i32 = host::display::state_get(1);
    let b: i32 = host::display::state_get(2);
    if host::display::pointer_down() == 1 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        if py >= 60 && py < 228 && px >= 16 && px < 240 {
            host::compose::focus_module(a);
        } else {
            if py >= 60 && py < 228 && px >= 272 && px < 496 {
                host::compose::focus_module(b);
            } else {
                host::compose::focus_module(-1);
            }
        }
    }
    let f: i32 = host::compose::focused();
    let mut ca: i32 = 0x303030;
    if f == a { ca = 0x00ff66; }
    let mut cb: i32 = 0x303030;
    if f == b { cb = 0x00ff66; }
    host::display::fill_rect(12, 56, 232, 2, ca);
    host::display::fill_rect(12, 230, 232, 2, ca);
    host::display::fill_rect(12, 56, 2, 176, ca);
    host::display::fill_rect(242, 56, 2, 176, ca);
    host::display::fill_rect(268, 56, 232, 2, cb);
    host::display::fill_rect(268, 230, 232, 2, cb);
    host::display::fill_rect(268, 56, 2, 176, cb);
    host::display::fill_rect(498, 56, 2, 176, cb);
    if host::compose::status(a) == 0 { host::display::draw_string(24, 130, "LOADING", 0xffff00, 1); }
    if host::compose::status(a) == 2 { host::display::draw_string(24, 130, "FAILED", 0xff0000, 1); }
    if host::compose::status(b) == 0 { host::display::draw_string(280, 130, "LOADING", 0xffff00, 1); }
    if host::compose::status(b) == 2 { host::display::draw_string(280, 130, "FAILED", 0xff0000, 1); }
    host::display::draw_number(8, 40, host::compose::module_count(), 0x808080, 1);
    host::display::present();
}
